//! Vendored gRPC stubs for the keel.reference.v1 contract (ADR-0022).
//!
//! The code under `src/genproto/` is generated by `buf generate` (prost + tonic;
//! see `buf.gen.yaml`) and committed; do not edit it by hand. This module includes
//! the generated package tree so the crate exposes it as
//! `keel_core::genproto::keel::reference::v1`.
//!
//! It is gated behind the opt-in `grpc` feature (mirroring the Python
//! `keel-core[grpc]` extra) so the default build pulls in neither prost nor tonic.

// Generated code: the derives, naming, and docs are the plugins' and are not held to
// the crate's lint/style bar. tonic/prost own the contents of the included files.
#[allow(
    clippy::all,
    clippy::pedantic,
    missing_docs,
    rustdoc::all,
    unreachable_pub
)]
pub mod keel {
    pub mod reference {
        pub mod v1 {
            include!("genproto/keel/reference/v1/keel.reference.v1.rs");
        }
    }
}
